import pytest

from app import audit
from app.errors import NotFoundError
from app.features.accounts import close_account


def test_close_account_removes_and_returns_balance():
    accounts = {"a1": 1250, "a2": 0}
    assert close_account(accounts, "a1") == 1250
    assert accounts == {"a2": 0}


def test_close_account_missing_raises_and_leaves_dict_unchanged():
    accounts = {"a1": 1250}
    before = dict(accounts)
    with pytest.raises(NotFoundError):
        close_account(accounts, "nope")
    assert accounts == before


def test_close_account_records_audit_event():
    audit.EVENTS.clear()
    close_account({"a1": 500}, "a1")
    assert audit.EVENTS[-1] == {
        "event": "account_closed",
        "account_id": "a1",
        "balance_cents": 500,
    }

